    // Portable code (experimental): milliseconds until the next `after()` / `elapsed()` timer of an active state expires.
    // Returns 0xFFFFFFFF when no timer is pending. A host can sleep this long, then dispatch the `do` event.
    // Other guard conditions are ignored, so the host may wake early but never late. Call it again after every dispatch.
    pub fn next_deadline_ms(&self) -> u32 {
        let mut best: u32 = 0xFFFFFFFF;
        let mut elapsed: u32 = 0;
        let mut duration: u32 = 0;
        
        // ON and its sub states
        if self.state_id >= StateId::ON && self.state_id <= StateId::IDLE {
            elapsed = self.vars.now_ms.wrapping_sub(self.vars.auto_off_from);
            duration = self.vars.auto_off_min.wrapping_mul(60000);
            if elapsed < duration && duration.wrapping_sub(elapsed) < best {
                best = duration.wrapping_sub(elapsed);
            }
        }
        
        // STEAM_ON and its sub states
        if self.on_region_1_state_id >= StateId::STEAM_ON && self.on_region_1_state_id <= StateId::STEAM_READY {
            elapsed = self.vars.now_ms.wrapping_sub(self.vars.steam_cmd_at);
            duration = self.vars.steam_cmd_max_ms;
            if elapsed < duration && duration.wrapping_sub(elapsed) < best {
                best = duration.wrapping_sub(elapsed);
            }
            elapsed = self.vars.now_ms.wrapping_sub(self.vars.STEAM_ON_entered_at);
            duration = self.vars.device_max_steam_ms;
            if elapsed < duration && duration.wrapping_sub(elapsed) < best {
                best = duration.wrapping_sub(elapsed);
            }
        }
        
        // BREWING
        if self.on_region_2_state_id == StateId::BREWING {
            elapsed = self.vars.now_ms.wrapping_sub(self.vars.BREWING_entered_at);
            duration = self.vars.brew_cmd_max_ms;
            if elapsed < duration && duration.wrapping_sub(elapsed) < best {
                best = duration.wrapping_sub(elapsed);
            }
            elapsed = self.vars.now_ms.wrapping_sub(self.vars.BREWING_entered_at);
            duration = self.vars.device_max_brew_ms;
            if elapsed < duration && duration.wrapping_sub(elapsed) < best {
                best = duration.wrapping_sub(elapsed);
            }
            elapsed = self.vars.now_ms.wrapping_sub(self.vars.last_write_at);
            duration = self.vars.heartbeat_timeout_ms;
            if elapsed < duration && duration.wrapping_sub(elapsed) < best {
                best = duration.wrapping_sub(elapsed);
            }
        }
        
        return best;
    }
