// Returns the parent state for a given state. Returns ROOT if input has no parent.
// Thread safe. This function can be disabled with `outputGetParentIdFunction` setting.
pub const fn get_parent_id(id: StateId) -> StateId {
    match id {
        StateId::ROOT => { return StateId::ROOT; }
        StateId::OFF => { return StateId::ROOT; }
        StateId::ON => { return StateId::ROOT; }
        StateId::ON_REGION_1 => { return StateId::ON; }
        StateId::STEAM_OFF => { return StateId::ON_REGION_1; }
        StateId::STEAM_ON => { return StateId::ON_REGION_1; }
        StateId::STEAM_HEATING => { return StateId::STEAM_ON; }
        StateId::STEAM_READY => { return StateId::STEAM_ON; }
        StateId::ON_REGION_2 => { return StateId::ON; }
        StateId::BREWING => { return StateId::ON_REGION_2; }
        StateId::FAULT => { return StateId::ON_REGION_2; }
        StateId::IDLE => { return StateId::ON_REGION_2; }
    }
}

